const softDeleteAlbumAssets = `-- name: SoftDeleteAlbumAssets :execrows
update assets
set status = 'deleted', deleted_at = now()
where status <> 'deleted'
  and asset_id in (select asset_id from album_photos where album_id = $1)
`

func (q *Queries) SoftDeleteAlbumAssets(ctx context.Context, albumID pgtype.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, softDeleteAlbumAssets, albumID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

